#!/usr/bin/env python3
"""Emit/check literal index mutator instructions from the pinned read-only ELF."""
import argparse
import hashlib
import re

from census import ORACLE, ROOT, extract


def generate_group(functions, stem, anchors, max_region_instructions=None):
    image = ['import Image', 'open Kraken.X64.Parser', f'namespace Binary.{stem}Image',
             '-- Generated by generate_index_mutators.py; no instruction substitution.']
    proofs = [f'import {stem}Image', 'import LayoutTactic',
              f'namespace Binary.{stem}Image', 'local instance : Labels := Image.linkedLabels']
    if stem == 'IndexInsert':
        proofs += ['-- Literal fetch traverses the complete 109-instruction list.',
                   'set_option maxRecDepth 2048']
    for name, namespace, count in anchors:
        [function] = [f for f in functions if f['name'] == name]
        rows = function['instructions']
        if len(rows) != count:
            raise ValueError(f'{name}: instruction count changed')
        starts = {function['entry']}
        for row in rows:
            raw = bytes.fromhex(row['bytes'])
            if branch := re.fullmatch(r'(j\w+|call) L_([0-9a-f]+)', row['normalized']):
                target = int(branch[2], 16)
                width = 1 if len(raw) == 2 else 4
                actual = (row['pc'] + len(raw) + int.from_bytes(raw[-width:], 'little', signed=True)) % 2**64
                if actual != target:
                    raise ValueError(f'branch encoding differs at {row["pc"]:x}')
                starts.update([target, row['pc'] + len(raw)])
        blocks = []
        for row in rows:
            if row['pc'] in starts or (max_region_instructions is not None and
                                      len(blocks[-1]) >= max_region_instructions):
                blocks.append([])
            blocks[-1].append(row)
        image += [f'namespace {namespace}', f'def entry : Int64 := .ofNat {function["entry"]}',
                  f'def byteSize : Nat := {function["size"]}', f'def instructionCount : Nat := {count}']
        regions = []
        for block in blocks:
            offset = block[0]['pc'] - function['entry']
            region = f'r{offset:02x}'
            regions.append(region)
            asm = '\n'.join(row['normalized'] for row in block)
            sizes = ', '.join(str(len(bytes.fromhex(row['bytes']))) for row in block)
            image += [f'def {region} : List (Kraken.Sized Directive) :=',
                      f'  List.zipWith (fun d n => ⟨d, n⟩) (parse("{asm}")) [{sizes}]']
            proofs += [f'theorem {namespace}_{region}_layout :',
                       f'    LaidOut {namespace}.fetch ({namespace}.entry + .ofNat {offset}) {namespace}.{region} := by',
                       '  binary_layout']
        image += ['def code : List (Kraken.Sized Directive) := ' + ' ++ '.join(regions),
                  'def fetch : Int64 → Option Decoded := Image.fetchIn entry code', f'end {namespace}']
    image += [f'end Binary.{stem}Image', '']
    proofs += [f'end Binary.{stem}Image', '']
    return {f'{stem}Image.lean': '\n'.join(image), f'{stem}Layout.lean': '\n'.join(proofs)}


def generated():
    expected = '06513d05fc37506b6cea546e8f11b9fe328e482265341ca41c242157bfa5e88e'
    if hashlib.sha256(ORACLE.read_bytes()).hexdigest() != expected:
        raise ValueError('wrong oracle image')
    functions = extract(ORACLE)
    return generate_group(functions, 'IndexMutator', [
        ('wg_index_hashtable_remove', 'Remove', 25),
        ('wg_index_hashtable_replace', 'Replace', 41),
    ]) | generate_group(functions, 'IndexInsert', [
        ('wg_index_hashtable_insert', 'Insert', 109),
    ])


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    for name, text in generated().items():
        path = ROOT / 'binary' / name
        if args.check:
            if path.read_text() != text:
                raise ValueError(f'{name} differs from the pinned image')
        else:
            path.write_text(text)
        print(f'{name}: {"checked" if args.check else "generated"}')


if __name__ == '__main__':
    main()
